const { randomUUID } = require('node:crypto');

// Use disposable Redis credentials, such as those generated by scripts/e2e.js.
const integrationTest = process.env.OPERATIONS_SECURITY_REDIS === '1' ? test : test.skip;

integrationTest('retries a transient SMTP failure and stores the settings OTP only on successful delivery', async () => {
  const prefix = `operations-security-${randomUUID()}`;
  const email = `${randomUUID()}@test.invalid`;
  const sendMail = jest.fn()
    .mockRejectedValueOnce(new Error('Transient SMTP failure'))
    .mockResolvedValueOnce({ messageId: 'delivered' });
  const bullmq = jest.requireActual('bullmq');
  const signalHandlers = ['SIGINT', 'SIGTERM'].map(signal => [signal, process.listeners(signal)]);
  let queue;
  let worker;
  let redisClient;

  jest.doMock('nodemailer', () => ({
    createTransport: () => ({ verify: jest.fn(), sendMail }),
  }));
  jest.doMock('bullmq', () => ({
    ...bullmq,
    Queue: class extends bullmq.Queue {
      constructor(name, options) {
        super(name, { ...options, prefix });
        queue = this;
      }
    },
    Worker: class extends bullmq.Worker {
      constructor(name, processor, options) {
        super(name, processor, { ...options, prefix });
        worker = this;
      }
    },
  }));
  jest.doMock('../../utils/logger', () => require('../../test-support/fixtures.cjs').loggerMock());

  try {
    const redis = require('../../config/redis');
    redisClient = await redis.initRedis();
    const storeOtp = jest.spyOn(redis, 'setOTP');
    const { enqueueSettingsOTP } = require('./emailservice');
    require('./emailworker');
    await Promise.resolve();
    await worker.waitUntilReady();

    const attempts = jest.fn();
    worker.on('failed', job => attempts(job.attemptsMade, storeOtp.mock.calls.length));
    const completed = new Promise(resolve => worker.once('completed', resolve));

    const { jobId } = await enqueueSettingsOTP(email, 'medical');
    // Bound the wait so failures still reach the resource cleanup below.
    let timer;
    try {
      const job = await Promise.race([
        completed,
        new Promise((_, reject) => {
          timer = setTimeout(() => reject(new Error('Email job did not complete after retry.')), 12_000);
        }),
      ]);
      expect(job.id).toBe(jobId);
      expect(job.attemptsMade).toBe(2);
      expect(attempts.mock.calls).toEqual([[1, 0]]);
      expect(sendMail).toHaveBeenCalledTimes(2);
      expect(sendMail.mock.calls[0]).toEqual(sendMail.mock.calls[1]);
      expect(storeOtp).toHaveBeenCalledTimes(1);
      await expect(redis.verifyOTP(email, 'settingsAction', job.data.data.otp, 'medical')).resolves.toBe(true);
    } finally {
      clearTimeout(timer);
    }
  } finally {
    for (const [signal, previous] of signalHandlers) {
      for (const handler of process.listeners(signal).filter(listener => !previous.includes(listener))) {
        process.removeListener(signal, handler);
      }
    }
    await worker?.close();
    try {
      await queue?.obliterate({ force: true });
    } finally {
      await queue?.close();
      await redisClient?.quit();
      jest.restoreAllMocks();
    }
  }
}, 20_000);
